INSERT INTO `evaluation_responses` (`id`, `evaluation_id`, `student_id`, `answers`, `submitted_at`, `created_at`, `updated_at`) VALUES
	(1, 1, 2, '{"1": 5, "2": 5, "3": "The hands-on activities were very practical and helpful for understanding hospitality operations.", "4": "Maybe include more case studies from real hotels."}', '2025-10-15 14:30:00', '2025-10-15 14:30:00', '2025-10-15 14:30:00'),
	(2, 1, 3, '{"1": 4, "2": 5, "3": "Customer service techniques were very well explained and demonstrated.", "4": "Would like to see more on conflict resolution in hospitality settings."}', '2025-10-15 15:45:00', '2025-10-15 15:45:00', '2025-10-15 15:45:00'),
	(3, 2, 9, '{"1": 5, "2": 5, "3": ["Leadership Strategies", "Career Development"], "4": "Excellent summit! The speakers were very engaging and knowledgeable."}', '2025-10-16 10:20:00', '2025-10-16 10:20:00', '2025-10-16 10:20:00'),
	(4, 2, 14, '{"1": 4, "2": 4, "3": ["Industry Trends", "Innovation"], "4": "Would like more focus on entrepreneurship in the next summit."}', '2025-10-16 11:15:00', '2025-10-16 11:15:00', '2025-10-16 11:15:00'),
	(5, 3, 26, '{"1": 5, "2": 5, "3": "The legal case studies were very relevant and practical for future law enforcement work.", "4": "Would like to see more on cybercrime and digital forensics."}', '2025-10-18 16:30:00', '2025-10-18 16:30:00', '2025-10-18 16:30:00'),
	(6, 4, 45, '{"1": 5, "2": 5, "3": ["Technology Integration", "Project-Based Learning"], "4": "Excellent seminar! Very practical and applicable to modern teaching."}', '2025-10-22 16:45:00', '2025-10-22 16:45:00', '2025-10-22 16:45:00'),
	(7, 5, 67, '{"1": 4, "2": 5, "3": ["Problem Solving", "Team Collaboration"], "4": "Great experience! The challenges were tough but very rewarding."}', '2025-10-25 20:00:00', '2025-10-25 20:00:00', '2025-10-25 20:00:00'),
